INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(13301, 'Psalms 27:4', 'Psalms', 27, 4, '&nbsp;د مالِک خُدائ نه هغه څۀ چې زۀ يې لټوم، زۀ دا يو سوال کوم، چې په کور د مالِک خُدائ کښې ټول عمر اوسېږم، او چې هغه په خپل کور کښې ولټوم چې د هغۀ د حُسن ديدن وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13302, 'Psalms 27:5', 'Psalms', 27, 5, '&nbsp;خو په سخته ورځ به هغه ما له په خپل مقدس کور کښې پناه راکړى، او په خپله خېمه کښې به هغه ما له حفاظت راکړى او ما به هغه پاس په لوړه د ګټ دپاسه کښېنوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13303, 'Psalms 27:6', 'Psalms', 27, 6, '&nbsp;نو بيا به زۀ خپله غړۍ هسکه کړم د هغوئ په وړاندې چا چې راګېر کړے يم، د هغۀ مقدس کور کښې به د خوشحالۍ په چغو قربانى وکړم، زۀ به سندرې او سرود او ثناء صِفت د مالِک خُدائ وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13304, 'Psalms 27:7', 'Psalms', 27, 7, '&nbsp;اے مالِکه خُدايه زما فرياد اوره کله چې زۀ سوال زارى کوم، مهربان شه، زما سوالونه قبول کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13305, 'Psalms 27:8', 'Psalms', 27, 8, '&nbsp;کله چې تا وفرمائيل، ”راشه زما ديدن وکړه،“ نو ما وئيل، ”اے مالِکه خُدايه، زۀ به درشم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13306, 'Psalms 27:9', 'Psalms', 27, 9, '&nbsp;خپل مخ رانه مۀ اړوه ما ته مۀ په قهر کېږه تۀ، خپل خِدمتګار دې غصه کښې مۀ پرېږده تۀ، اے پاکه خُدايه، اوس ما مۀ پرېږده او ما مۀ رد کوه زما خلاصونکے يې تۀ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13307, 'Psalms 27:10', 'Psalms', 27, 10, '&nbsp;کۀ څۀ هم چې مور او پلار ما ځان له پرېږدى، خو مالِک خُدائ به ما خپل ځان ته نزدې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13308, 'Psalms 27:11', 'Psalms', 27, 11, '&nbsp;اے مالِکه خُدايه، ما ته خپله لار راوښايه، ځکه چې دشمن زما په انتظار کښې دے نو په نېغه لار مې بوځه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13309, 'Psalms 27:12', 'Psalms', 27, 12, '&nbsp;ما د دشمنانو لاسونو ته مۀ پرېږده، ځکه چې دوئ په ما هغه تهمت لګوى کوم چې ما کړے نۀ وى، هره لحظه او شېبه کښې د شرارت دهمکى راکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13310, 'Psalms 27:13', 'Psalms', 27, 13, '&nbsp;زما يقين دے د مالِک خُدائ مهربانى به ووينم، ترڅو چې زۀ دلته په دې دُنيا کښې يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13311, 'Psalms 27:14', 'Psalms', 27, 14, '&nbsp;نو مالِک خُدائ ته په صبر او انتظار شه، نو ډاډه شه او زړَور شه او د مالِک خُدائ په صبر او انتظار شه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13312, 'Psalms 28:1', 'Psalms', 28, 1, '&nbsp;زۀ تا ته زارى کومه، اے مالِکه خُدايه زما حفاظت کوونکيه، خپل غوږونه دې په ما مۀ کڼوه. کۀ چرې تۀ پاتې شې خاموشه، زۀ به هم د هغه چا په شان شم چې روان وى قبرستان ته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13313, 'Psalms 28:2', 'Psalms', 28, 2, '&nbsp;زما دُعا واوره او په ما رحم وکړه کله چې زۀ تا ته د مدد دپاره فرياد وکړم، چې کله هم زۀ خپل لاسونه ستا مقدس مقام په لورې پورته کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13314, 'Psalms 28:3', 'Psalms', 28, 3, '&nbsp;ما لرى مۀ غورزوه د بدکارانو سره، او څوک چې بد کوى کارونه د هغوئ سره، څوک چې کوى په خولۀ خوږې خبرې ګاونډيانو سره خو په زړۀ کښې جوړوى منصوبې د فسادونو سره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13315, 'Psalms 28:4', 'Psalms', 28, 4, '&nbsp;هغوئ ته د هغوئ د عملونو سزا ورکړه هغوئ ته د هغوئ د بدو کارونو په اندازه بدله ورکړه، هغوئ ته د خپلو بدو عملونو او کارونو بدله ورکړه کوم ‎چې دوئ د نورو سره کړى دى هغوئ ته د هغه څۀ سزا ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13316, 'Psalms 28:5', 'Psalms', 28, 5, '&nbsp;ځکه چې هغوئ د مالِک خُدائ د کارونو نه بې‌پرواه دى او د هغۀ د لاسونو کړې کارونه نۀ وينى، هغه به هغوئ ښکته راګزار کړى، او هيڅکله به بيا آباد نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13317, 'Psalms 28:6', 'Psalms', 28, 6, '&nbsp;ثناء صِفت دې مالِک خُدائ ته وى، ځکه چې د رحم دپاره هغۀ زما ژړا واورېدله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13318, 'Psalms 28:7', 'Psalms', 28, 7, '&nbsp;مالِک خُدائ زما قوت دے زما ډال دے، زما په هغۀ د خپل ټول زړۀ سره يقين دے، هغۀ ما سره مدد وکړو، او زړۀ مې خوشحاله دے، زۀ به د ثناء صِفت سندرو سره د هغۀ شکريه ادا کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13319, 'Psalms 28:8', 'Psalms', 28, 8, '&nbsp;مالِک خُدائ خپلو خلقو له طاقت ورکوى، هغه د خپل مسح شوى بادشاه يوه محفوظه قلعه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13320, 'Psalms 28:9', 'Psalms', 28, 9, '&nbsp;بچ کړه خپل خاص خلق او ورته برکت ورکړه، شپون د هغوئ جوړ شه تل يې په خپلو لاسونو کښې اوچت کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13321, 'Psalms 29:1', 'Psalms', 29, 1, '&nbsp;اے د آسمان مخلوقه، د مالِک خُدائ ثناء صِفت وکړئ، د مالِک خُدائ د جلال او د طاقت ثناء صِفت وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13322, 'Psalms 29:2', 'Psalms', 29, 2, '&nbsp;د مالِک خُدائ د جلالى نوم ثناء صِفت وکړئ، د مالِک خُدائ عبادت د هغۀ د مقدس شان په مطابق وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13323, 'Psalms 29:3', 'Psalms', 29, 3, '&nbsp;آواز د مالِک خُدائ د دريابونو دپاسه اورېدے شى، د تندر په شان، د زورَورو اوبو دپاسه د جلالى خُدائ آواز اورېدے شى د تندر په شان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13324, 'Psalms 29:4', 'Psalms', 29, 4, '&nbsp;آواز د مالِک خُدائ ډېر زورَور دے، د مالِک خُدائ د آواز لوئ شان دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13325, 'Psalms 29:5', 'Psalms', 29, 5, '&nbsp;د مالِک خُدائ آواز د زورَور دِيار ونې ماتوى، د مالِک خُدائ آواز د لبنان د دِيار ونې ماتوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13326, 'Psalms 29:6', 'Psalms', 29, 6, '&nbsp;هغه د لبنان غرونه په ټوپونو کوى د سخى په شان، هغه د حرمون غر په ټوپونو کوى لکه د ځوان ځنګلى غوَيى په شان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13327, 'Psalms 29:7', 'Psalms', 29, 7, '&nbsp;د مالِک خُدائ آواز شُغله کوى لکه د برېښنا په شان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13328, 'Psalms 29:8', 'Psalms', 29, 8, '&nbsp;د مالِک خُدائ آواز صحراګانې لړزوى، د مالِک خُدائ آواز د قادِس دشته خوځوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13329, 'Psalms 29:9', 'Psalms', 29, 9, '&nbsp;د مالِک خُدائ آواز د څېړۍ ونې کږوى او د ځنګلى ونو پاڼې رژوى، د هغۀ په کور کښې هر يو چغې وهى چې، ”خُدائ لوئ ‎‎دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13330, 'Psalms 29:10', 'Psalms', 29, 10, '&nbsp;مالِک خُدائ په سېلاب باندې هم خپل حکومت کوى، مالِک خُدائ د تل دپاره بادشاهى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13331, 'Psalms 29:11', 'Psalms', 29, 11, '&nbsp;طاقت ورکوى خپلو خلقو له په خپله مالِک خُدائ، د امن او امان برکت ورکوى خپلو خلقو له په خپله مالِک خُدائ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13332, 'Psalms 30:1', 'Psalms', 30, 1, '&nbsp;اے مالِکه خُدايه ستا ثناء صِفت بيانوم، ځکه چې تا زۀ بچ کړم، زۀ دې د دشمنانو د مسخرو نۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13333, 'Psalms 30:2', 'Psalms', 30, 2, '&nbsp;اے مالِکه زما خُدايه، ما مدد دپاره تا ته زارى وکړله او تا ما له شفا راکړله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13334, 'Psalms 30:3', 'Psalms', 30, 3, '&nbsp;اے مالِکه خُدايه تا زۀ د قبر نه راوويستم، تا زۀ د مرګ کندې ته د غورزېدو نه بچ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13335, 'Psalms 30:4', 'Psalms', 30, 4, '&nbsp;اے مقدسينو مالِک خُدائ ته سندرې ووايئ، د هغۀ د مقدس نوم ثناء صِفت ادا کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13336, 'Psalms 30:5', 'Psalms', 30, 5, '&nbsp;ځکه چې د هغۀ غضب يوه لحظه وى، خو د هغۀ فضل د ټول عمر وى، ژړا صرف د شپې وى، خو سحر کښې بيا خوشحالى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13337, 'Psalms 30:6', 'Psalms', 30, 6, '&nbsp;کله چې زۀ ښۀ ومه نو ما داسې وئيل، ”زۀ به هيڅکله په لړزان نۀ شم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13338, 'Psalms 30:7', 'Psalms', 30, 7, '&nbsp;اے مالِکه خُدايه، لکه غر په شان ستا فضل زۀ قوى کړم، چې مخ دې رانه واړولو نو زۀ شومه مايوسه او حېران.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13339, 'Psalms 30:8', 'Psalms', 30, 8, '&nbsp;اے مالِکه خُدايه، ما تا ته ژړا او فرياد وکړو ما مالِک ته د رحم سوال وکړو او ومې وئيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13340, 'Psalms 30:9', 'Psalms', 30, 9, '&nbsp;”تا ته څۀ فائده ده چې زۀ مړ شم، او ګور ته لاړ شم؟ زما خاورې ستا ثناء صِفت کولے شى څۀ؟ دا ستا وفادارى بيانولے شى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13341, 'Psalms 30:10', 'Psalms', 30, 10, '&nbsp;اے مالِکه خُدايه، رحم په ما وکړه سوال مې واوره، اے مالِکه خُدايه، زما مددګار شه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13342, 'Psalms 30:11', 'Psalms', 30, 11, '&nbsp;تا زما وير د خوشحالۍ په ګډا باندې بدل کړو، تا رانه د غم جامې کوزې کړې او د خوشحالۍ لباس دې راکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13343, 'Psalms 30:12', 'Psalms', 30, 12, '&nbsp;نو ستا ثناء صِفت به کوم او خاموش به نۀ شم. اے مالِکه خُدايه، زما پاکه خُدايه، زۀ به د ټول عمر دپاره ستا شکريه ادا کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13344, 'Psalms 31:1', 'Psalms', 31, 1, '&nbsp;اے مالِکه خُدايه، زۀ تا له د پناه دپاره راغلے يم، ما بچ کړه چې زۀ ونۀ شرمېږم. په خپل عدالت کښې دې ما له خلاصون راکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13345, 'Psalms 31:2', 'Psalms', 31, 2, '&nbsp;خپل غوږ دې ما ته راواړوه زر راشه او خلاصون راکړه ما له، زما د بچ کولو ګټ او مضبوطه قلعه جوړه شه چې په کوم کښې به امان راکوې ما له.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13346, 'Psalms 31:3', 'Psalms', 31, 3, '&nbsp;تۀ زما ګټ او زما قلعه يې. د خپل نوم د خاطره دې زما لارښودنه وکړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13347, 'Psalms 31:4', 'Psalms', 31, 4, '&nbsp;ما د هغه دام نه آزاد کړه چې کوم يې په پټه خور کړے دے، ځکه چې تۀ زما د پناه ځائ يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13348, 'Psalms 31:5', 'Psalms', 31, 5, '&nbsp;زۀ ستا لاسونو ته خپل روح سپارم، مالِکه خُدايه تۀ وفادار خُدائ يې تا زۀ بچ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13349, 'Psalms 31:6', 'Psalms', 31, 6, '&nbsp;څوک چې د بې‌کاره بُتانو عبادت کوى د هغوئ نه زما نفرت دے. اے مالِکه خُدايه په تا باندې زما يقين دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13350, 'Psalms 31:7', 'Psalms', 31, 7, '&nbsp;زۀ به ستا ابدى مينه کښې خندا او خوشحالى کوم، ځکه چې تا په تکليفونو کښې وليدم، او تۀ زما د زړۀ په مشکلاتو کوې پام.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13351, 'Psalms 31:8', 'Psalms', 31, 8, '&nbsp;زۀ دې د دشمن لاسونو ته ورنۀ کړم پراخه مېدان ته دې زۀ بوتلم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13352, 'Psalms 31:9', 'Psalms', 31, 9, '&nbsp;اے مالِکه خُدايه په ما مهربان شه په سختۍ کښې يم، د غم په وجه د سترګو نظر مې لاړو ړوند شوم، په بدن او روح کمزورے شوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13353, 'Psalms 31:10', 'Psalms', 31, 10, '&nbsp;ژوند مې په غم تير شو، د خفګان سره مې عمر لنډ شو، ګناهونو مې زور ختم کړے دے، او هډُوکى مې کمزورى شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13354, 'Psalms 31:11', 'Psalms', 31, 11, '&nbsp;دشمنان او ګاونډيان ټول راته په سپکه سترګه ګورى، تر دې چې دوستان هم ما ته د نزدې راتلو نه يريږى. کله چې ما کوڅو کښې ووينى، دوئ بل طرف ته زغلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13355, 'Psalms 31:12', 'Psalms', 31, 12, '&nbsp;لکه مړے چې څوک هېر کړى داسې هېر شوم، زۀ لکه د يو مات لوښى په شان جوړ شوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13356, 'Psalms 31:13', 'Psalms', 31, 13, '&nbsp;د ځان په حقله ما د ډېرو افواګانې واورېدلې، او د هرې خوا نه په يرو کښې راګېر شوم. زما د ختمولو منصوبې دشمن جوړې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13357, 'Psalms 31:14', 'Psalms', 31, 14, '&nbsp;خو اے مالِکه خُدايه په تا دے يقين زما، وايمه چې، ”هم تۀ خُدائ يې زما.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13358, 'Psalms 31:15', 'Psalms', 31, 15, '&nbsp;ستا په لاسونو کښې دے مستقبل زما، د دشمنانو نه مې بچ کړه څوک چې ظلم کوى په ما.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13359, 'Psalms 31:16', 'Psalms', 31, 16, '&nbsp;خپله د مخ رڼا دې په خپل خِدمتګار وځلوه. په خپله نۀ ختمېدونکې مينې سره دې ما بچ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13360, 'Psalms 31:17', 'Psalms', 31, 17, '&nbsp;چې زۀ ونۀ شرمېږمه اے مالِکه خُدايه، خو د مدد دپاره زۀ تا ته فرياد کوم. بدعمله دې شرمنده شى، هغوئ دې په لحد کښې غلې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13361, 'Psalms 31:18', 'Psalms', 31, 18, '&nbsp;د هغوئ دروغژنې ژبې دې غلې شى هغه مغرورې ژبې چې نېکانو پسې سپکې وائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13362, 'Psalms 31:19', 'Psalms', 31, 19, '&nbsp;ستا احسان څومره لوئ وى چې تا ساتلى د هغه چا دپاره څوک چې تا نه يريږى. هر هغه چا ته يې زيات ورکوې څوک چې تا ته د پناه دپاره راځى، او د ټولو خلقو په وړاندې هغوئ له برکت ورکوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13363, 'Psalms 31:20', 'Psalms', 31, 20, '&nbsp;د خپل حضور د سورې لاندې تۀ هغوئ له پناه ورکوې، تۀ هغوئ د خلقو د پټو منصوبو نه بچ ساتې، او په خپل حضور کښې د خلقو د سپکو خبرو نه ورله پناه ورکوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13364, 'Psalms 31:21', 'Psalms', 31, 21, '&nbsp;د مالِک خُدائ ثناء دې وى، هغۀ ما ته خپله خاص مينه وښودله کله چې زۀ ګېر شوى ښار کښې محاصره وم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13365, 'Psalms 31:22', 'Psalms', 31, 22, '&nbsp;نو د يرې نه ما چغه کړه چې، ”زۀ د مالِک نظر نه غورزېدلے يم.“ خو تا زما واورېدل کله چې زۀ د مدد دپاره ژړېدلے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13366, 'Psalms 31:23', 'Psalms', 31, 23, '&nbsp;اے ټولو مقدسينو د مالِک خُدائ سره مينه کوئ، مالِک خُدائ خپل وفادار بچ کوى، او د کبرژنو نه پوره بدله اخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13367, 'Psalms 31:24', 'Psalms', 31, 24, '&nbsp;نو تاسو زړَور او تکړه اوسئ، اے ټولو څوک چې د مالِک خُدائ نه اُميد لرئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13368, 'Psalms 32:1', 'Psalms', 32, 1, '&nbsp;بختور دى هغوئ د چا نافرمانى چې معاف شوه، او د چا په ګناهونو چې پړده واچولے شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13369, 'Psalms 32:2', 'Psalms', 32, 2, '&nbsp;نو څومره بختور هغه کس دے د چا بد چې مالِک خُدائ حساب نۀ کړى او څوک چې په خپل ژوند کښې ټګى نۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13370, 'Psalms 32:3', 'Psalms', 32, 3, '&nbsp;خو چې کله ما خپله ګناه پټوله، نو زما بدن کمزورے کېدلو او ټوله ورځ هډوکو به مې درد کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13371, 'Psalms 32:4', 'Psalms', 32, 4, '&nbsp;هر کله چې شپه او ورځ ستا د اصلاح دروند لاس په سر وو زما، لکه په سختې ګرمۍ کښې زور شو ختم زما.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13372, 'Psalms 32:5', 'Psalms', 32, 5, '&nbsp;نو آخر هم ما د خپلې ګناه اقرار وکړو تا ته خو ما پټې نۀ کړې خپلې خطاګانې له تا نه. نو ما ووئيل خپل ځان سره چې، ”خپله سرکشى به مالِک خُدائ ته بيان کړم.“ نو بيا تا زما د ګناهونو خطا معاف کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13373, 'Psalms 32:6', 'Psalms', 32, 6, '&nbsp;نو د دې دپاره هر څوک چې نېکان وى هغوئ دې هم دا اوس دُعا وغواړى له تا نه، بې‌شکه دوئ ته به ونۀ رسيږى تکليفونه کۀ هم راشى لوئ سېلابونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13374, 'Psalms 32:7', 'Psalms', 32, 7, '&nbsp;تۀ زما پناه ګاه يې او د تکليفونو نه دې بچ کړم، او زۀ دې د کاميابۍ په نغمو کښې تاو کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13375, 'Psalms 32:8', 'Psalms', 32, 8, '&nbsp;مالِک خُدائ فرمائى، زۀ به تا ته ښۀ او نېغه لار ستا د ژوند دپاره دروښايم. زۀ به تا ته نصيحت کوم او په تا به نظر ساتم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13376, 'Psalms 32:9', 'Psalms', 32, 9, '&nbsp;د مست آس يا قچر په شان مۀ جوړېږئ چې د واګو او قېزې نه بغېر نۀ قابو کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13377, 'Psalms 32:10', 'Psalms', 32, 10, '&nbsp;بدکارانو او شريرانو له غمونه ډېر وى، خو د چا چې په هغۀ باندې توکل وى د مالِک خُدائ مينه د هغۀ نه ګېرچاپېره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13378, 'Psalms 32:11', 'Psalms', 32, 11, '&nbsp;نو په مالِک خُدائ کښې خوشحاله اوسئ، تاسو ټول چې د هغۀ تابعدار يئ، د خوشحالۍ چغې ووهئ، تاسو د چا زړونه چې صفا دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13379, 'Psalms 33:1', 'Psalms', 33, 1, '&nbsp;اے صادقانو، مالِک خُدائ ته د خوشحالۍ سندرې ووايئ، دا د صادقانو دپاره ښۀ دى چې د هغۀ ثناء ووائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13380, 'Psalms 33:2', 'Psalms', 33, 2, '&nbsp;د بينجو د ساز سره د مالِک خُدائ ثناء خوان شئ، د رباب په لسو تارو ساز کښې د هغۀ ثناء خوان شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13381, 'Psalms 33:3', 'Psalms', 33, 3, '&nbsp;په نوې حمد د هغۀ ثناء صِفت ادا کړئ، په حکمت سره رباب ووهئ، او د خوشحالۍ دپاره چغې ووهئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13382, 'Psalms 33:4', 'Psalms', 33, 4, '&nbsp;د مالِک خُدائ کلام رښتونے دے، څۀ چې هغه کوى ټول د اطمينان دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13383, 'Psalms 33:5', 'Psalms', 33, 5, '&nbsp;مالِک خُدائ د صداقت او اِنصاف سره مينه کوى، د هغۀ په ازلى مينې ټوله زمکه ډکه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13384, 'Psalms 33:6', 'Psalms', 33, 6, '&nbsp;د مالِک خُدائ په کلام سره جوړ شوى آسمانونه دى، د هغۀ د خولې په کلام نمر، سپوږمۍ او ټول ستورى جوړ شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13385, 'Psalms 33:7', 'Psalms', 33, 7, '&nbsp;هغۀ د سمندر اوبۀ په يو ځائ جمع کړى دى، هغۀ د سمندر اوبۀ په ذخيرو کښې بندې کړې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13386, 'Psalms 33:8', 'Psalms', 33, 8, '&nbsp;د مالِک خُدائ نه دې ټوله دُنيا يره وکړى، د زمکې هر کس دې د هغۀ احترام وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13387, 'Psalms 33:9', 'Psalms', 33, 9, '&nbsp;نو چې هغۀ وفرمائيل، دُنيا پېدا شوه، د هغۀ په حُکم ژوند پېدا شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13388, 'Psalms 33:10', 'Psalms', 33, 10, '&nbsp;مالِک خُدائ د قومونو منصوبې بې‌نتيجې کوى، هغه د هغوئ ټولې منصوبې باطلوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13389, 'Psalms 33:11', 'Psalms', 33, 11, '&nbsp;خو د مالِک خُدائ منصوبې به د تل دپاره قائمې شى، او د هغۀ ارادې به هيڅکله خوځولے نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13390, 'Psalms 33:12', 'Psalms', 33, 12, '&nbsp;څومره بختور دے هغه قوم د چا خُدائ چې مالِک خُدائ وى، او د خپل ميراث دپاره چې هغۀ غوره کړى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13391, 'Psalms 33:13', 'Psalms', 33, 13, '&nbsp;د آسمان نه مالِک خُدائ لاندې ګورى او هغه ټول بنيادمان وينى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13392, 'Psalms 33:14', 'Psalms', 33, 14, '&nbsp;د خپل تخت نه هغه کتل کوى ټول خلق وينى کوم چې په زمکه اوسېدل کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13393, 'Psalms 33:15', 'Psalms', 33, 15, '&nbsp;هغه د ټولو د زړونو جوړونکے دے، نو د هغوئ په هر عمل هغه خبر دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13394, 'Psalms 33:16', 'Psalms', 33, 16, '&nbsp;يو بادشاه به هم د خپل لښکر په ډيروالى بچ نۀ شى، او نۀ به کوم تکړه سپاهى په خپل زور تښتېدے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13395, 'Psalms 33:17', 'Psalms', 33, 17, '&nbsp;د خلاصون دپاره جنګى آس بې‌فائدې شى، هغه په خپل ټول زور بيا هم تا بچ کولے نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13396, 'Psalms 33:18', 'Psalms', 33, 18, '&nbsp;مالِک خُدائ په هغوئ نظر ساتى څوک چې د هغۀ نه يريږى، په هغوئ باندې چې د هغۀ په ازلى مينه اُميد ساتى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13397, 'Psalms 33:19', 'Psalms', 33, 19, '&nbsp;هغه دوئ د مرګ نه بچ ساتى او د قحط په وخت کښې يې ژوندى ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13398, 'Psalms 33:20', 'Psalms', 33, 20, '&nbsp;مونږ په مالِک خُدائ باندې توکل کوُو، هغه زمونږ مدد او زمونږ ډال دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13399, 'Psalms 33:21', 'Psalms', 33, 21, '&nbsp;په هغۀ کښې زمونږ زړونه خوشحاله دى، او د هغۀ په پاک نوم زمونږ ايمان دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13400, 'Psalms 33:22', 'Psalms', 33, 22, '&nbsp;مالِکه خُدايه، ستا ابدى مينه دې مونږ سره وى. لکه څنګه چې له تا نه زمونږ اُميد وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');